const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
function gray(frame){const a=[];for(let i=0;i<frame.pixels.length;i+=3)a.push((frame.pixels[i]*.2126+frame.pixels[i+1]*.7152+frame.pixels[i+2]*.0722)/255);return a}
function normalized(frame){const a=gray(frame),m=mean(a),sd=Math.sqrt(mean(a.map(v=>(v-m)**2)));return {a:a.map(v=>(v-m)/Math.max(.08,sd)),brightness:m,contrast:sd}}
export function estimateScale(a,b,width,height){
 if(a.length!==width*height||b.length!==a.length)return null;
 const error=(scale,dx,dy)=>{let sum=0,n=0;for(let y=4;y<height-4;y+=2)for(let x=4;x<width-4;x+=2){const ax=(x-width/2-dx)/scale+width/2,ay=(y-height/2-dy)/scale+height/2,ix=Math.floor(ax),iy=Math.floor(ay);if(ix<0||iy<0||ix+1>=width||iy+1>=height)continue;const u=ax-ix,v=ay-iy,value=a[iy*width+ix]*(1-u)*(1-v)+a[iy*width+ix+1]*u*(1-v)+a[(iy+1)*width+ix]*(1-u)*v+a[(iy+1)*width+ix+1]*u*v;sum+=Math.min(2,Math.abs(value-b[y*width+x]));n++}return n?sum/n:Infinity};
 let base=Infinity,best={error:Infinity,scale:1};for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){base=Math.min(base,error(1,dx,dy));for(let i=-10;i<=15;i++){const scale=1+i*.01,e=error(scale,dx,dy);if(e<best.error)best={error:e,scale,dx,dy}}}return {...best,baseline:base,improvement:base>0?(base-best.error)/base:0};
}
export function detectVisualEffects(samples,shot){
 const f=samples.filter(s=>s.time>=shot.start&&s.time<shot.end&&s.pixels?.length).sort((a,b)=>a.time-b.time).map(s=>({...s,...normalized(s)}));const effects=[];if(f.length<3)return effects;
 const addFade=(kind,range)=>{const first=range[0],last=range.at(-1);effects.push({kind,start:first.time,end:last.time,title:kind==='fade-in'?'淡入候选':'淡出候选',reason:`${range.length} 个连续采样的整体亮度${kind==='fade-in'?'上升':'下降'}，连接近黑画面；也可能来自光线或曝光变化。`,parameters:`不透明度 ${kind==='fade-in'?'0% → 100%':'100% → 0%'}；约 ${(last.time-first.time).toFixed(2)} 秒（采样估计）`,steps:[`定位 ${first.time.toFixed(2)}–${last.time.toFixed(2)} 秒，选中片段，打开不透明度参数。`,`在该区间首尾添加关键帧：${kind==='fade-in'?'0% → 100%':'100% → 0%'}。`,`背景使用黑色，逐帧核对过渡时间；这是单片段透明度方案，不是两段叠化。`]})};
 if(f[0].brightness<.035){let end=1;while(end<f.length-1&&f[end+1].time-f[0].time<=2&&f[end+1].brightness-f[end].brightness>.012)end++;const range=f.slice(0,end+1);if(range.length>=3&&range.at(-1).brightness>.12&&range.slice(1).every((s,i)=>s.brightness>=range[i].brightness-.015))addFade('fade-in',range)}
 if(f.at(-1).brightness<.035){let start=f.length-2;while(start>0&&f.at(-1).time-f[start-1].time<=2&&f[start-1].brightness-f[start].brightness>.012)start--;const range=f.slice(start);if(range.length>=3&&range[0].brightness>.12&&range.slice(1).every((s,i)=>s.brightness<=range[i].brightness+.015))addFade('fade-out',range)}
 const usable=f.filter(s=>s.brightness>.12&&s.brightness<.88&&s.contrast>.06);if(usable.length>=5){const a=usable[0],b=usable[Math.floor(usable.length/2)],c=usable.at(-1),w=a.pixelWidth,h=a.pixelHeight;if(w&&h&&c.time-a.time>=.6){const fit=estimateScale(a.a,c.a,w,h),middle=estimateScale(a.a,b.a,w,h);if(fit&&middle&&Math.abs(fit.scale-1)>=.03&&fit.improvement>.18&&fit.error<.28&&(fit.scale-1)*(middle.scale-1)>0&&Math.abs(middle.scale-1)<=Math.abs(fit.scale-1)+.01){const endScale=Math.round(fit.scale*100);effects.push({kind:'scale',start:a.time,end:c.time,title:fit.scale>1?'放大 / 推近候选':'缩小 / 拉远候选',reason:`对齐首、中、末采样后，整体缩放匹配比仅平移匹配的误差降低 ${(fit.improvement*100).toFixed(0)}%。可能为后期缩放、实拍运镜或主体移动，不能确定原实现。`,parameters:`以 ${a.time.toFixed(2)} 秒画面为 100%，至 ${c.time.toFixed(2)} 秒约 ${endScale}%（图像匹配估计，不是原工程参数）`,steps:[`选中片段，在 ${a.time.toFixed(2)} 秒为缩放和位置添加关键帧。`,`在 ${c.time.toFixed(2)} 秒尝试缩放 ${endScale}%，调位置使画面中的固定背景对齐。`,`回放对比中间画面；若出现明显视差或主体独立移动，关键帧缩放只能近似，原片可能使用实拍运镜。`]})}}}
 return effects.sort((a,b)=>a.start-b.start);
}
export function visualEffectCard(samples,shot){const items=detectVisualEffects(samples,shot),box=document.createElement('section');box.className='visual-effects';const add=(tag,text,parent=box)=>{const e=document.createElement(tag);e.textContent=text;parent.append(e);return e};add('h4','自动效果检测 · 像素分析');if(!items.length)add('p','未检测到满足当前条件的淡入、淡出或整体缩放线索。不能因此排除其他效果。');for(const item of items){const card=add('div','');add('h4',`${item.start.toFixed(2)}–${item.end.toFixed(2)} 秒 · ${item.title}`,card);add('p',item.reason,card);add('p',item.parameters,card);const list=add('ol','',card);item.steps.forEach(step=>add('li',step,list))}return box}
export function visualEffectsReport(samples,shots){return '\n\n## 自动效果检测（像素证据候选，不是原工程识别）\n'+shots.map((s,i)=>`### 镜头 ${i+1}\n`+detectVisualEffects(samples,s).map(e=>`${e.start.toFixed(2)}–${e.end.toFixed(2)} 秒：${e.title}\n${e.reason}\n${e.parameters}\n${e.steps.join('\n')}`).join('\n\n')).join('\n\n')}
